<?php $adopters=rows("SELECT DISTINCT u.* FROM users u JOIN applications a ON a.user_id=u.id AND a.status='Approved' WHERE u.name LIKE ? OR u.email LIKE ? OR u.phone LIKE ? ORDER BY u.name",array_fill(0,3,'%'.$search.'%'));if(!$adopters)echo '<div class="empty">Approved adopters will appear here after application review.</div>';foreach($adopters as $a):?><section class="panel"><h2><?=e($a['name'])?></h2><p><?=e($a['email'])?> · <?=e($a['phone'])?></p><p class="muted"><?=e($a['address'])?></p><details><summary>Contact history</summary><?php foreach(rows('SELECT c.*,u.name author FROM contacts c JOIN users u ON u.id=c.created_by WHERE c.user_id=? ORDER BY c.id DESC',[$a['id']]) as $c):?><p><?=nl2br(e($c['note']))?><small><?=e($c['author'])?> · <?=e($c['created_at'])?></small></p><?php endforeach;formStart('contact');?><input type="hidden" name="user_id" value="<?=$a['id']?>"><?php area('Add contact note','note');button('Record contact');?></details></section><?php endforeach;
